Here is a basic JavaScript applet that simulates a pendulum. It uses the canvas element to draw the pendulum and the requestAnimationFrame function to update the animation. It also takes into account the physics laws of gravity, including the acceleration of gravity (9.8 m/s^2) and the initial angle of the pendulum.

```
// define some constants
const gravity = 9.8;
const initialAngle = 0;
const pendulumLength = 100;
const frameRate = 60;

// get the canvas and set up the context
const canvas = document.getElementById('pendulum');
const ctx = canvas.getContext('2d');

// set the canvas dimensions
canvas.width = 500;
canvas.height = 300;

// set up the initial state of the pendulum
let angle = initialAngle;
let angleRate = 0;
let time = 0;
let paused = true;

// function to update the state of the pendulum
function update() {
  time += 1 / frameRate;

  // update the angle and angle rate
  angleRate = -gravity * Math.sin(angle) / pendulumLength;
  angle += angleRate * (1 / frameRate);

  // check if the pendulum has reached its equilibrium
  if (Math.abs(angleRate) < 0.01) {
    paused = true;
  }
}

// function to draw the pendulum
function draw() {
  // clear the canvas
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // draw the pendulum arm
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, pendulumLength, 0, 2 * Math.PI);
  ctx.fillStyle = 'rgba(0, 0, 255, 0.5)';
  ctx.fill();

  // draw the pendulum bob
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, 10, 0, 2 * Math.PI);
  ctx.fillStyle = 'rgba(255, 0, 0, 0.5)';
  ctx.fill();

  // draw the angle of the pendulum
  ctx.beginPath();
  ctx.arc(canvas.width / 2, canvas.height / 2, pendulumLength, 0, 2 * Math.PI);
  ctx.strokeStyle = 'rgba(0, 0, 0, 0.5)';
  ctx.lineWidth = pendulumLength * 0.1;
  ctx.arc(canvas.width / 2, canvas.height / 2, pendulumLength, 0, Math.PI - angle);
  ctx.stroke();
}

// function to handle the button click
function pendulumButtonClicked() {
  paused = false;
  angle = initialAngle;
  angleRate = 0;
  time = 0;
}

// main loop
function animate() {
  if (!paused) {
    update();
    draw();
  }
  requestAnimationFrame(animate);
}

// add event listener to the button
document.getElementById('pendulum-button').addEventListener('click', pendulumButtonClicked);

// start the animation
animate();
```

